pub enum Msg {
    Ping,
    Hello(String),
    Heartbeat(u32),
}

pub fn decode(bytes: &str) -> Result<Msg, String> {
    if bytes.contains("ping") {
        return Ok(Msg::Ping);
    }
    if let Some(value) = bytes
        .strip_prefix(r#"{"v":2,"hello":""#)
        .and_then(|value| value.strip_suffix(r#""}"#))
    {
        return Ok(Msg::Hello(value.into()));
    }
    if let Some(value) = bytes
        .strip_prefix(r#"{"v":2,"heartbeat":"#)
        .and_then(|value| value.strip_suffix('}'))
    {
        if let Ok(sequence) = value.parse() {
            return Ok(Msg::Heartbeat(sequence));
        }
    }
    Err("unknown".into())
}

pub fn encode(msg: &Msg) -> String {
    match msg {
        Msg::Ping => "ping".into(),
        Msg::Hello(value) => format!(r#"{{"v":2,"hello":"{}"}}"#, value),
        Msg::Heartbeat(sequence) => format!(r#"{{"v":2,"heartbeat":{}}}"#, sequence),
    }
}
pub fn ping_roundtrip() -> Result<Msg, String> {
    decode(&encode(&Msg::Ping))
}

#[cfg(test)]
mod tests {
    use super::{decode, encode, Msg};

    #[test]
    fn decodes_ping_frame() {
        assert!(matches!(decode("ping"), Ok(Msg::Ping)));
    }
    #[test]
    fn hello_roundtrip_uses_v2_envelope() {
        let encoded = encode(&Msg::Hello("world".into()));
        assert_eq!(encoded, r#"{"v":2,"hello":"world"}"#);
        assert!(matches!(decode(&encoded), Ok(Msg::Hello(value)) if value == "world"));
    }
    #[test]
    fn heartbeat_roundtrip_preserves_sequence() {
        let encoded = encode(&Msg::Heartbeat(42));
        assert_eq!(encoded, r#"{"v":2,"heartbeat":42}"#);
        assert!(matches!(decode(&encoded), Ok(Msg::Heartbeat(sequence)) if sequence == 42));
    }

}
